function renderColoring(){const cur=state.coloring||colorings[0],fill=state.fill||palette[0];return `<div class="lesson coloring-game"><h2>🎨 涂颜色</h2><p>选图画、选颜色，再点要上色的地方</p><div class="coloring-choices">${colorings.map(x=>`<button class="coloring-choice ${x[0]===cur[0]?'active':''}" onclick="chooseColoring('${x[0]}')"><img src="img/coloring/${x[0]}.png" alt=""><span>${x[1]}</span></button>`).join('')}</div><div class="palette">${palette.map(c=>`<button class="${fill===c?'active':''}" style="background:${c}" onclick="setFill('${c}',this)" aria-label="选择颜色"></button>`).join('')}</div><canvas id="colorPad" width="560" height="560"></canvas><div class="color-actions"><button id="colorUndo" onclick="undoColoring()" disabled>↶ 撤销一步</button><button onclick="resetColoring()">↻ 重新涂</button><button class="finish-coloring" onclick="finishArtwork('colorPad')">⭐ 保存作品</button><button onclick="nextColoring()">换一张 →</button></div><div class="art-save-message" id="artSaveMessage" aria-live="polite"></div></div>`}
function initColoring(){const c=$('#colorPad');if(!c)return;const x=c.getContext('2d',{willReadFrequently:true}),img=new Image();state.colorUndo=[];state.colorReady=false;img.onload=()=>{x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);const r=Math.min(c.width/img.width,c.height/img.height),w=img.width*r,h=img.height*r;x.drawImage(img,(c.width-w)/2,(c.height-h)/2,w,h);state.colorReady=true};img.src='img/coloring/'+(state.coloring||colorings[0])[0]+'.png';c.onpointerup=e=>{if(!state.colorReady)return;e.preventDefault();const r=c.getBoundingClientRect(),sx=Math.floor((e.clientX-r.left)*c.width/r.width),sy=Math.floor((e.clientY-r.top)*c.height/r.height),before=x.getImageData(0,0,c.width,c.height);if(!floodFill(x,sx,sy,state.fill||palette[0]))return;state.colorUndo.push(before);if(state.colorUndo.length>8)state.colorUndo.shift();$('#colorUndo').disabled=false;tone(520,.08)};state.colorCtx=x}
function floodFill(ctx,sx,sy,hex){const im=ctx.getImageData(0,0,ctx.canvas.width,ctx.canvas.height),d=im.data,w=im.width,h=im.height,i0=(sy*w+sx)*4,target=[d[i0],d[i0+1],d[i0+2]],rgb=hex.match(/\w\w/g).map(x=>parseInt(x,16));if(target.every((v,i)=>Math.abs(v-rgb[i])<8)||(target[0]<80&&target[1]<80&&target[2]<80))return false;const seen=new Uint8Array(w*h),q=[sx,sy];let head=0,count=0;while(head<q.length&&count<w*h){const x=q[head++],y=q[head++],p=y*w+x;if(x<0||y<0||x>=w||y>=h||seen[p])continue;seen[p]=1;const i=p*4;if(Math.abs(d[i]-target[0])>38||Math.abs(d[i+1]-target[1])>38||Math.abs(d[i+2]-target[2])>38)continue;d[i]=rgb[0];d[i+1]=rgb[1];d[i+2]=rgb[2];count++;q.push(x+1,y,x-1,y,x,y+1,x,y-1)}if(!count)return false;ctx.putImageData(im,0,0);return true}
