function renderPiano(){if(window.MUSIC_STUDIO)return window.MUSIC_STUDIO.render();const keys=[['do','#ff746c',261.6],['re','#ffad5c',293.7],['mi','#ffd65a',329.6],['fa','#6ed19d',349.2],['sol','#65b8ff',392],['la','#8b91ff',440],['si','#b788ed',493.9],['do','#ef7eba',523.3]];return `<div class="lesson"><h2>🎹 音乐小琴</h2><p>点琴键，听听声音有什么不同</p><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0">${keys.map(k=>`<button onclick="tone(${k[2]})" style="height:120px;border-radius:20px;background:${k[1]};color:white;font-size:20px;font-weight:900">${k[0]}</button>`).join('')}</div><button class="wide-btn" onclick="playSong()">▶ 听一段小星星</button></div>`}
