// Native update navigation was introduced in Android 2.3.0. The old online
// wrapper also identifies itself as GuolichengTablet, but cannot handle it.
function supportsAndroidAppUpdates(userAgent){
  const version=String(userAgent||'').match(/(?:^|\s)GuolichengTablet\/(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-Offline)?(?=\s|$)/);
  if(!version)return false;
  const [major,minor,patch]=version.slice(1).map(Number);
  if(![major,minor,patch].every(Number.isSafeInteger))return false;
  return major>2||(major===2&&minor>=3);
}
